import{c as r,U as n,j as a,g as t,o,a6 as i,n as l}from"./chunks/framework.h4W4t1IS.js";const b=JSON.parse('{"title":"Contexte","description":"","frontmatter":{"title":"Contexte","status":"ready","tags":["architecture","all"],"authors":["Jean-François Dion"],"reviewers":[]},"headers":[],"relativePath":"architecture/contexte.md","filePath":"architecture/contexte.md"}'),u={name:"architecture/contexte.md"},c={id:"frontmatter-title",tabindex:"-1"};function d(s,e,p,m,g,h){return n(),a("div",null,[t("h1",c,[o(i(s.$frontmatter.title)+" ",1),e[0]||(e[0]=t("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1))]),e[1]||(e[1]=l('<p>Le <strong>Contexte</strong> donne accès aux services <strong>partagés</strong> de l&#39;application, comme les repositories. Il est créé une seule fois, à l&#39;amorçage, puis transmis là où on en a besoin pour construire les contrôleurs.</p><h2 id="objectifs-d-apprentissage" tabindex="-1">Objectifs d&#39;apprentissage <a class="header-anchor" href="#objectifs-d-apprentissage" aria-label="Permalink to &quot;Objectifs d&#39;apprentissage&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Après cette section, tu seras capable de...</p><ul><li>Expliquer le rôle du Contexte dans l&#39;application</li><li>Distinguer les dépendances partagées (stateful) des dépendances recréées à chaque requête (stateless)</li><li>Éviter les fuites de mémoire causées par une reconfiguration répétée du graphe d&#39;objets</li></ul></div><h2 id="role" tabindex="-1">Rôle <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Rôle&quot;">​</a></h2><p><strong>Responsabilités :</strong></p><ul><li>Créer une seule fois les services partagés (repositories, etc.)</li><li>Les fournir à ceux qui construisent les contrôleurs et les vues</li></ul><h2 id="etat-partage-vs-etat-par-requete" tabindex="-1">État partagé vs état par requête <a class="header-anchor" href="#etat-partage-vs-etat-par-requete" aria-label="Permalink to &quot;État partagé vs état par requête&quot;">​</a></h2><p>Toutes les dépendances ne se comportent pas de la même façon lorsqu&#39;elles sont recréées. La différence tient à ce que l&#39;objet contient :</p><ul><li>Un objet <strong>stateful</strong> (avec état) contient des <strong>données</strong> qui évoluent pendant l&#39;exécution. Ses attributs conservent de l&#39;information, par exemple la liste des chiens d&#39;un <a href="/420-w30-sf-po2/lexique.html#repository" class="lexicon-link" title="Patron de conception qui fournit une interface pour accéder aux données d&#39;une source de données, encapsulant la logique de persistance et permettant de séparer les préoccupations entre la couche de domaine et la couche d&#39;accès aux données.">repository</a> en mémoire. Recréer l&#39;objet, c&#39;est perdre ces données.</li><li>Un objet <strong>stateless</strong> (sans état) contient seulement de la <strong>logique</strong> et des <strong>références vers ses collaborateurs</strong> (contrôleur, vue, etc.), reçues à la construction. Ces attributs ne changent plus ensuite : une nouvelle instance se comporte exactement comme l&#39;ancienne.</li></ul><table tabindex="0"><thead><tr><th>Type</th><th><a href="/420-w30-sf-po2/lexique.html#composition" class="lexicon-link" title="Mécanisme qui établit une relation A_UN entre un objet composé et ses composants, auxquels il délègue les comportements qu&#39;il ne réalise pas lui-même.">Composition</a> interne</th><th>Exemple</th><th>Cycle de vie</th></tr></thead><tbody><tr><td><strong>Stateful (partagé)</strong></td><td>Données qui évoluent (ex. <code>List&lt;Chien&gt;</code>)</td><td>Repositories en mémoire</td><td>Une seule instance, détenue par le Contexte</td></tr><tr><td><strong>Stateless</strong></td><td>Logique et références vers ses collaborateurs</td><td>Contrôleurs et vues</td><td>Peuvent être recréés à chaque requête</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Contrôleurs observateurs : une seule instance</p><p>Un contrôleur est généralement recréé à chaque requête. Mais lorsqu&#39;il est aussi un <a href="/420-w30-sf-po2/lexique.html#observateur" class="lexicon-link" title="Patron de conception qui définit une dépendance unidirectionnelle entre des objets, permettant à un objet (l&#39;observateur) de surveiller les changements d&#39;un autre objet (le sujet) et d&#39;être notifié automatiquement en cas de modification.">observateur</a>, par exemple abonné à un repository, il doit exister en une <strong>instance unique</strong>, créée une seule fois à l&#39;amorçage et réutilisée pour chaque requête.</p><p>Le contrôleur reste stateless, puisqu&#39;il ne contient que des références vers ses collaborateurs, mais le repository conserve une référence vers lui. S&#39;il était recréé à chaque requête, chaque nouvelle instance viendrait s&#39;ajouter à la liste d&#39;observateurs, sans que les anciennes soient <strong>jamais désabonnées</strong>. La liste grossirait indéfiniment : c&#39;est une fuite de mémoire incrémentielle, difficile à détecter parce qu&#39;elle ne cause pas d&#39;erreur immédiate.</p><p>Tout objet référencé par une dépendance <strong>stateful</strong> doit donc être construit <strong>une seule fois</strong> et réutilisé, plutôt que recréé et reconfiguré à répétition.</p></div><h2 id="avantages" tabindex="-1">Avantages <a class="header-anchor" href="#avantages" aria-label="Permalink to &quot;Avantages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Avantage</th><th>Description</th></tr></thead><tbody><tr><td><strong>Services partagés uniques</strong></td><td>Les repositories existent en un seul exemplaire pour toute l&#39;application</td></tr><tr><td><strong>Testabilité</strong></td><td>En test, un autre Contexte peut fournir des repositories simulés</td></tr><tr><td><strong><a href="/420-w30-sf-po2/lexique.html#inversion-des-dependances" class="lexicon-link" title="Principe SOLID qui stipule de dépendre des abstractions (interfaces) plutôt que des implémentations concrètes, autant pour les modules de haut niveau que de bas niveau.">DIP</a></strong></td><td>Les contrôleurs reçoivent des <a href="/420-w30-sf-po2/lexique.html#abstraction" class="lexicon-link" title="Un des quatre piliers de la POO : se concentrer sur ce qu&#39;un objet fait plutôt que sur comment il le fait. Se réalise en Java par les classes abstraites et les interfaces.">abstractions</a>, pas des implémentations</td></tr></tbody></table>',13))])}const q=r(u,[["render",d]]);export{b as __pageData,q as default};
